def link(ref):
    name, sep, lineno = ref.strip().rpartition(':')
    if not sep or not lineno.isdigit(): name,lineno=ref.strip(),''
    target=(ROOT/name).as_posix()
    return f'[{ref.strip()}](<{target}{":"+lineno if lineno else ""}>)'
def refs(s): return '; '.join(link(x) for x in s.split(';'))

